INSERT INTO posts (id, title, slug, content, excerpt, featured_image, author_id, status, is_featured, view_count, published_at, created_at, updated_at) VALUES (4, 'test23', 'test23', '<p>âsdasdasdasdNhưng giờ đây, hai ta chia cách muôn trùng mây Giấc mơ ngàn thu đón anh bình yên chốn ấy Trong tương lai một mình em trên lối đi này Thương nhớ hoài kỷ niệm xưa chung bước dưới mưa bay. Ngày hôm nao chia tay anh nói như lời trăn trối em đừng u sầu Gạt lệ thương đau nếu chúng ta không còn nhau. Con đường em và anh nguyện đi suốt đời Một khi không còn anh là qua hết rồi Chỉ mong có ai cùng em bước tiếp mới vui lòng anh Và hôm nay em đang đi tới trên đoạn đường mới như lời anh rồi Một hạnh phúc mới em hứa cho anh mỉm cười Cho dù em và ai cùng đi suốt đời Thì vẫn như còn anh cùng em chung lối Em ước rằng, chốn xa xôi anh được yên vui.</p><p>&nbsp;</p><figure class="image"><img style="aspect-ratio:1583/678;" src="/uploads/posts/posts_editor/1775138566666_Screenshot_2025-12-20_152016.png" width="1583" height="678" alt="hello mấy con vợ"></figure>', 'nói chung là hay lắm', '/uploads/posts/1775138587613_049bj.png', NULL, 'published', 1, 5, '2026-04-02T07:03:07.612Z', '2026-04-02T07:02:48.454Z', '2026-04-02T07:14:49.897Z');
